from decimal import Decimal

from .money import _MAX_AMOUNT, _context, parse_amount, format_amount


def make_invoice(amounts):
    items = list(amounts)  # copy; never touch the caller's sequence
    ctx = _context()
    total = Decimal("0.00")
    for item in items:
        total = ctx.add(total, parse_amount(item))
        if total > _MAX_AMOUNT:
            raise ValueError("invoice total must be at most 1000000.00")
    return {"total": format_amount(total), "count": len(items)}
